import{c as o,Q as r,j as l,m as a}from"./chunks/framework.rWdQudnF.js";const c=JSON.parse('{"title":"虚拟机风格","description":"","frontmatter":{"title":"虚拟机风格"},"headers":[],"relativePath":"综合知识/架构设计/架构风格与模式/虚拟机风格.md","filePath":"综合知识/架构设计/架构风格与模式/虚拟机风格.md","lastUpdated":null}'),n={name:"综合知识/架构设计/架构风格与模式/虚拟机风格.md"};function s(e,t,i,d,g,h){return r(),l("div",null,[...t[0]||(t[0]=[a('<blockquote><p>虚拟机风格的核心：<strong>自定义规则供使用者使用</strong>，灵活定义，跨平台适配。</p></blockquote><h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] 解释器：解释引擎 + 存储区 + 数据结构</li><li>[ ] 基于规则的系统：规则集 + 解释器 + 选择器 + 工作内存</li><li>[ ] 两者区分（规则系统→AI/DSS，解释器→自定义逻辑）</li><li>[ ] 解释器缺点（执行效率低）</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="解释器" tabindex="-1">解释器 <a class="header-anchor" href="#解释器" aria-label="Permalink to &quot;解释器&quot;">​</a></h3><p><strong>四大组成：</strong></p><ol><li><strong>解释引擎</strong> — 完成解释工作</li><li><strong>存储区</strong> — 存储被解释代码</li><li><strong>工作状态数据结构</strong> — 记录引擎工作状态</li><li><strong>执行进度数据结构</strong> — 记录源代码被执行进度</li></ol><ul><li>缺点：<strong>执行效率低</strong></li><li>可通过<strong>预先编译部分解释代码</strong>提高性能</li></ul><h3 id="基于规则的系统" tabindex="-1">基于规则的系统 <a class="header-anchor" href="#基于规则的系统" aria-label="Permalink to &quot;基于规则的系统&quot;">​</a></h3><p><strong>四大组成：</strong></p><ol><li><strong>规则集</strong> — 存储规则</li><li><strong>规则解释器</strong> — 解释执行规则</li><li><strong>规则/数据选择器</strong> — 选择适当规则和数据</li><li><strong>工作内存</strong> — 存放当前事实和数据</li></ol><ul><li>一般用在<strong>人工智能领域</strong>和 <strong>DSS（决策支持系统）</strong></li><li>适合<strong>业务规则频繁变化</strong>的场景</li><li>灵活组合，自定义规则</li></ul><h3 id="🎯-二者区分-高频考题" tabindex="-1">🎯 二者区分（高频考题） <a class="header-anchor" href="#🎯-二者区分-高频考题" aria-label="Permalink to &quot;🎯 二者区分（高频考题）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>选哪个</th></tr></thead><tbody><tr><td>业务灵活组合、自定义规则</td><td>规则系统</td></tr><tr><td>自定义逻辑执行、用户定义对象行为</td><td><strong>解释器</strong></td></tr><tr><td>大型即时战略游戏（玩家自定义）</td><td><strong>解释器</strong></td></tr><tr><td>机器人（根据规则调整行为）</td><td><strong>规则系统</strong></td></tr><tr><td>Java &quot;一次编写到处运行&quot;</td><td><strong>虚拟机</strong>（解释器风格）</td></tr></tbody></table><blockquote><p>⚠️ <strong>考题套路</strong>：看到&quot;用户自行定义&quot;→ 解释器（游戏、IDE）；看到&quot;规则调整&quot;→ 规则系统（机器人、专家系统）。</p></blockquote>',15)])])}const _=o(n,[["render",s]]);export{c as __pageData,_ as default};
